-- INSERTA DATOS FICTICIOS EN LA BASE EXISTENTE. No crea ni modifica tablas.
-- Conserva usuarios y roles; usa únicamente ana_admin. No actualiza ni borra registros existentes.
-- Ejecutar mediante sqlcmd -b. Si ya hay códigos DEMO, se detiene sin duplicarlos.
USE DB_keyove_inventario;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
BEGIN TRY
BEGIN TRANSACTION;
DECLARE @duena int;
SELECT @duena=u.iCodUsuario FROM Usuarios u JOIN Roles r ON r.iCodRol=u.iCodRol
WHERE u.cNombreUsuario='ana_admin' AND u.bEstado=1 AND r.cNombre='Administrador' AND r.bEstado=1;
IF @duena IS NULL THROW 51000, 'No existe la administradora activa ana_admin.', 1;
IF EXISTS(SELECT 1 FROM Productos WITH(UPDLOCK,HOLDLOCK) WHERE cCodigo LIKE 'DEMO-P-%')
 OR EXISTS(SELECT 1 FROM Proveedores WITH(UPDLOCK,HOLDLOCK) WHERE cRuc BETWEEN '20000000001' AND '20000000030')
 OR EXISTS(SELECT 1 FROM Categorias WITH(UPDLOCK,HOLDLOCK) WHERE cNombre LIKE 'DEMO %')
 OR EXISTS(SELECT 1 FROM Compras WITH(UPDLOCK,HOLDLOCK) WHERE cNumeroComprobante LIKE 'DEMO-C-%')
 OR EXISTS(SELECT 1 FROM Ventas WITH(UPDLOCK,HOLDLOCK) WHERE cNumeroComprobante LIKE 'DEMO-V-%')
 OR EXISTS(SELECT 1 FROM Personas WITH(UPDLOCK,HOLDLOCK) WHERE cCorreo LIKE 'persona%@example.test')
 THROW 51000, 'Ya existen datos DEMO o códigos coincidentes. No se insertó el lote.', 1;
DECLARE @persona int, @usuario int, @categoria int, @proveedor int,
        @producto int, @compra int, @venta int, @fecha date, @imagen varbinary(max);
INSERT Personas(cNombres,cApellidos,cGenero,cCorreo,cTelefono,dFechaNacimiento)
VALUES(N'Ana','DE PRUEBA 01','F','persona01@example.test','900000001','19900101');
