IF EXISTS (SELECT 1 FROM Productos p WHERE p.cCodigo LIKE 'DEMO-P-%' AND p.iStockActual <>
 (SELECT SUM(CASE WHEN m.cTipoMovimiento='ENTRADA' THEN m.iCantidad ELSE -m.iCantidad END)
 FROM Movimientos_Inventario m WHERE m.iCodProducto=p.iCodProducto))
 THROW 51001, 'El inventario de prueba no coincide con sus movimientos.', 1;
IF (SELECT COUNT(*) FROM Productos WHERE cCodigo LIKE 'DEMO-P-%')<>30
 OR (SELECT COUNT(*) FROM Compras WHERE cNumeroComprobante LIKE 'DEMO-C-%')<>30
 OR (SELECT COUNT(*) FROM Ventas WHERE cNumeroComprobante LIKE 'DEMO-V-%')<>30
 THROW 51001, 'La carga de prueba no quedó completa.', 1;
COMMIT TRANSACTION;
PRINT 'Carga completada: 330 registros nuevos; usuarios y roles conservados.';
